  /** Whole tons to buy into the stores to reach `safe_tons` (rounded up). */
  buy_tons: number;
  /**
   * `stores_below_safe`: the stores hold less than the route's `safe_provisions_tons`, so one
   * storm or pirate hit (a storm takes a rolled share of the stores, pirates a fifth to a half)
   * can leave the crew unfed before port, and a starving crew may mutiny, which no insurance
   * pays for.
   */
  code: string;
  detail: string;
  /** Provisions in the stores at departure (tons, fractional). */
  have_tons: number;
  /**
   * Least the stores must hold (tons, fractional) to reach port fed with this cargo and no
   * hazards.
   */
  required_tons: number;
  /** The route's `safe_provisions_tons` (survives one hazard on any leg). */
