export interface ExpansionStatusResult {
  /**
   * Companies that traded within the last 7 game days or have a ship at sea now (NPC houses
   * excluded): what the tier in play is sized for, recomputed every world-director tick.
   */
  active_trading_companies: number;
  /** Completed tiers, earliest first. */
  completed_tiers: ExpansionTierStatus[];
  current_tier?: null | ExpansionTierStatus;
  unlocked_phase: number;
}

/** One expansion tier's progress and contribution leaderboard. */
export interface ExpansionTierStatus {
  /** Active trading companies when the target was last recomputed. */
  active_companies: number;
  /**
   * Tons the open charters still accept, combined (more than `tons_remaining`: no single
   * charter is required).
   */
  charter_capacity_tons: number;
  /** The tier's charters (the tier in play only): open ones and full ones. */
  charters: ExpansionCharterProgress[];
  /** Unlocked its phase. */
  completed: boolean;
  completed_at?: string | null;
  /**
   * Split among the contributors when the tier completes, by player with diminishing returns
   * (pro rata to the square root of each player's contribution), so not by `share_bps`.
   */
  completion_bonus_pence: Pence;
  /** Every contributor, largest share first. */
  contributors: ExpansionContributor[];
  min_tons: number;
  /** `tons_delivered / target_tons`, in bps (capped at 10,000). */
  progress_bps: number;
  /** The phase this tier unlocks. */
  target_phase: number;
  /**
   * The tier's target tonnage: `tons_per_company` per active trading company, at least
   * `min_tons` (as last sized, see `active_companies`).
   */
  target_tons: number;
  title: string;
  /**
   * Tons delivered against the tier so far, across all its charters: the tier completes when
   * this reaches `target_tons`.
   */
  tons_delivered: number;
  tons_per_company: number;
  /** `target_tons - tons_delivered` (0 once completed). */
  tons_remaining: number;
}

