  /** 1-indexed month of the year (`1..=12`). */
  month: number;
  /** Current meteorological [`Season`]. */
  season: Season;
  /** Active simulation time scale multiplier (e.g. `60` = 60 game seconds per 1 real second). */
  time_scale: number;
  /** Cumulative in-game hours elapsed since `season_epoch` (world time, from 1 March 1700). */
