  prototype_port_id?: null | PortId;
  slot: Slot;
  /** 1 drawings, 2 prototype, 3 sea trials, 4 Admiralty board. */
  stage: number;
  stage_name: string;
  stage_points: number;
  stage_points_required: number;
  start_fee_pence: number;
  started_at: string;
  /** `active`, `granted` or `abandoned`. */
